/**
 * Grades free-text answers.
 *
 * Grounded questions (generated by the RAG service, with key points and
 * source chunks) are graded by the RAG service: point-by-point against the
 * source pages, with feedback and page citations. Older questions without
 * sources fall back to the legacy Gemini grader. Both paths return the same
 * shape, so callers and the UI handle one format.
 */

function toCitationOut(c) {
  return {
    chunkId: c.chunk_id ?? c.chunkId,
    pageStart: c.page_start ?? c.pageStart,
    pageEnd: c.page_end ?? c.pageEnd,
    pageLabelStart: c.page_label_start ?? c.pageLabelStart,
    pageLabelEnd: c.page_label_end ?? c.pageLabelEnd,
    snippet: c.snippet,
  };
}

const isGrounded = (q) => Boolean(q && q.grounded && q.sourceChunkIds && q.sourceChunkIds.length);

function createGrader({ rag, runLegacy }) {
  async function gradeGrounded(userId, items) {
    const res = await rag.grade({
      userId,
      items: items.map(({ question, userAnswer }) => ({
        question: question.question,
        reference_answer: question.correctAnswer,
        key_points: question.keyPoints || [],
        source_chunk_ids: question.sourceChunkIds,
        answer: String(userAnswer ?? ''),
      })),
    });
    return res.results.map((r, i) => ({
      is_correct: r.verdict === 'correct',
      verdict: r.verdict,
      accuracy: r.score,
      missing_points: r.missing_points,
      feedback: r.feedback,
      citations: (r.citations || []).map(toCitationOut),
      correct_answer: items[i].question.correctAnswer,
      user_answer: String(items[i].userAnswer ?? ''),
      grader: 'rag-points-v1',
    }));
  }

  async function gradeLegacy(items) {
    const results = await runLegacy({
      answers: items.map((it) => String(it.userAnswer ?? '')),
      correct_answers: items.map((it) => it.question.correctAnswer || 'No answer available'),
    });
    return results.evaluations.map((e, i) => ({
      is_correct: e.is_correct,
      verdict: e.is_correct ? 'correct' : 'incorrect',
      accuracy: e.accuracy,
      missing_points: e.missing_points || [],
      feedback: null,
      citations: [],
      correct_answer: e.correct_answer ?? items[i].question.correctAnswer,
      user_answer: e.user_answer ?? String(items[i].userAnswer ?? ''),
      grader: 'legacy-gemini',
    }));
  }

  /** items: [{question: QuestionDoc, userAnswer}] -> evaluations in the same order */
  async function grade(userId, items) {
    const grounded = [];
    const legacy = [];
    items.forEach((it, i) => (isGrounded(it.question) && rag.isEnabled() ? grounded : legacy).push(i));

    const out = new Array(items.length);
    const jobs = [];
    if (grounded.length) {
      jobs.push(gradeGrounded(userId, grounded.map((i) => items[i])).then((rs) => rs.forEach((r, j) => (out[grounded[j]] = r))));
    }
    if (legacy.length) {
      jobs.push(gradeLegacy(legacy.map((i) => items[i])).then((rs) => rs.forEach((r, j) => (out[legacy[j]] = r))));
    }
    await Promise.all(jobs);
    return out;
  }

  return { grade };
}

let defaultGrader;
function getGrader() {
  if (!defaultGrader) {
    const { ragClient } = require('../utils/ragClient');
    const { runPythonProcess } = require('../utils/pythonRunner');
    defaultGrader = createGrader({
      rag: ragClient,
      runLegacy: (data) => runPythonProcess('./python_scripts/evaluate_answers.py', [JSON.stringify(data)]),
    });
  }
  return defaultGrader;
}

module.exports = { createGrader, getGrader, isGrounded, toCitationOut };
